from html import escape
import json
from .evidence import sanitize

def html_report(result):
    result = sanitize(result)
    e=lambda x:escape(str(x))
    rows=''.join(f'<article><h2>{e(f["title"])}</h2><p class="severity">{e(f["severity"].upper())} · {e(f["id"])} · Confidence: {e(f.get("confidence", "unknown"))} · Source: {e(f.get("source", "legacy"))}</p><h3>Observed evidence</h3><p>{e(f["evidence"])}</p><h3>Recommended remediation</h3><p>{e(f["remediation"])}</p></article>' for f in result['findings'])
    return f'''<!doctype html><html lang="en"><meta charset="utf-8"><title>Sentinel assessment</title><style>body{{font:16px system-ui;max-width:850px;margin:40px auto;padding:0 20px;color:#172a3e}}article{{border-top:1px solid #cbd5df;padding:12px 0}}.severity{{font-weight:bold;color:#8b4513}}h3{{font-size:15px}}small{{color:#536579}}</style><h1>Sentinel / Security assessment</h1><p><b>Target:</b> {e(result['target'])}<br><b>UTC:</b> {e(result['started'])}<br><b>Status:</b> {e(result['status'])}<br><b>HTTP:</b> {e(result['http_status'])}<br><b>TLS negotiated:</b> {e(result['tls'])}</p><p>{e(result['error'])}</p><p><b>Profile:</b> {e(result.get('profile','web-v1'))}<br><b>Optional DNS domain:</b> {e(result.get('dns_domain') or 'Not requested')}</p><h2>Assessment coverage</h2><pre style="white-space:pre-wrap">{e(json.dumps(result.get('coverage',{'profile':'legacy v0.1'}),indent=2))}</pre><p><b>{len(result['findings'])} observations.</b> Findings are configuration indicators, not proof of exploitability. No findings does not establish that the assessed target is secure.</p>{rows}<small>Scope and limitations depend on the selected profile; see Assessment coverage above. Severity indicates potential impact; confidence describes evidence strength, not exploitability. Evidence is redacted on a best-effort basis. Review reports before sharing.</small></html>'''
